WITH base AS (SELECT *, INITCAP(TRIM(location)) AS location_title FROM departments WHERE budget IS NOT NULL), DepartmentsStats AS (SELECT CASE WHEN budget >= 3614000 THEN 'high' WHEN budget >= 1199000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(CASE WHEN dept_name = 'Sales' THEN 1 END) AS sales_count FROM base GROUP BY CASE WHEN budget >= 3614000 THEN 'high' WHEN budget >= 1199000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, sales_count FROM DepartmentsStats WHERE sales_count >= 9
